def get_isolation_score(r, c, grid):
    """Compute isolation score around 2x3 pattern at (r, c) - the 5x5 window border"""
    # 5x5 window: rows r-1 to r+4, cols c-1 to c+4
    zeros = 0
    total = 0
    for i in range(-1, 5):
        for j in range(-1, 5):
            ri, cj = r + i, c + j
            if 0 <= ri < 15 and 0 <= cj < 15:
                total += 1
                if grid[ri][cj] == 0:
                    zeros += 1
    return zeros, total

def find_patterns(grid):
